def insert_position(xs: list[int], x: int) -> int:
    """Return the leftmost index where x could be inserted to keep the list sorted."""
    lo, hi = 0, len(xs)
    while lo < hi:
        mid = (lo + hi) // 2
        if xs[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo


def count_occurrences(xs: list[int], x: int) -> int:
    """Return how many times x appears in the sorted list xs."""
    # Find leftmost index where x could be inserted
    lo, hi = 0, len(xs)
    while lo < hi:
        mid = (lo + hi) // 2
        if xs[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    left = lo

    # Find rightmost index where x could be inserted (i.e., first index where xs[mid] > x)
    lo, hi = 0, len(xs)
    while lo < hi:
        mid = (lo + hi) // 2
        if xs[mid] <= x:
            lo = mid + 1
        else:
            hi = mid
    right = lo

    return right - left
